pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    let residual = post_residual as f64;
    let next = next_item_size as f64;
    let mean = mean_residual.max(0.0);

    // Prefer leaving enough room for the known next item.
    if next > 0.0 {
        if residual >= next {
            score -= 24.0;
        } else {
            score += 18.0;
        }

        // Strongly reward an exact or near-exact two-item match.
        let mismatch = (residual - next).abs();
        score -= 14.0 * (-mismatch / 20.0).exp();

        // Avoid needlessly fragmenting the remaining stream.
        if residual < next {
            score += 5.0 * (next - residual).min(20.0);
        }
    } else {
        // At stream end, compact the current bin aggressively.
        score -= 9.0 * (residual as f64 / bin_capacity.max(1) as f64);
    }

    // Reward residuals near the population mean, penalize unusually bad holes.
    let mean_gap = (residual - mean).abs();
    score -= 7.0 * (-mean_gap / 18.0).exp();
    if residual < next {
        score += 6.0 * (next - residual).min(20.0);
    }

    // A residual that can accommodate no plausible future item is costly.
    if residual > 0.0 && residual < 10.0 {
        score += 14.0;
    } else if residual == 0.0 {
        score -= 10.0;
    }

    // If this is the only fitting bin, favor closing or preserving it strategically.
    if fitting_bins_count == 1 {
        if next > 0.0 && residual < next {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Early in a long stream, tolerate some waste to preserve good pairing options.
    // Later, compact aggressively and prefer a new bin over a poor fit.
    let new_bin_bias = if bin_residual == bin_capacity {
        -18.0 * (1.0 - progress) + 7.0 * progress
    } else {
        0.0
    };

    score += new_bin_bias;

    // Slightly discourage opening many bins while alternatives exist.
    if open_bins_count > 1 && fitting_bins_count > 1 {
        score += 0.03 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space below the practical minimum incoming-item size is wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 + (10.0 - post_residual as f64) * 4.0;
    }

    // Moderate gaps are also less useful than larger, readily reusable gaps.
    if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.2;
    }

    // Reward placing into a bin that is already reasonably tight.
