        score -= 18.0;
    } else if post_residual <= item_size / 2 {
        score -= 6.0;
    }

    // Preserve a fitting bin if this is the last opportunity to use it.
    if fitting_bins_count == 1 && bin_residual > bin_capacity / 2 {
        score += 8.0;
    }

    // New bins are sensible when many bins remain open and the stream is mature.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;
    } else {
        // Mild pressure to consolidate as the number of open bins grows.
        score += open_bins_count as f64 * 0.35;

        // Prefer residuals close to the observed mean among open bins.
        score += (post_residual as f64 - mean_residual).abs() * 0.18;
    }

    // Lookahead: retain room for the next item when that is materially valuable.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 7.0;
    }

    score
}

