    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        1.0
    };

    let pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += 7.0 * pressure;

    let dead_space_threshold = (next_item_size as f64 * 0.75).max(1.0);
