        score += 24.0 + 12.0 * (dead_space_threshold - post_residual as f64);
    }

    if post_residual == 0 {
        score -= 18.0;
    } else if post_residual < 10 {
        score += 16.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    if fitting_bins_count == 1 {
        score += 10.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        score += 28.0 + 10.0 * pressure;
    }

    let capacity = bin_capacity as f64;
    if capacity > 0.0 {
        let fill_penalty = (post_residual as f64 / capacity).powi(2) * 12.0;
        score += fill_penalty;
    }

    let mean_bonus = (mean_residual - post_residual as f64).clamp(-20.0, 20.0);
    score -= 0.35 * mean_bonus;

    if next_item_size == 0 {
        score -= 3.0 * progress;
    }

    score
