pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let residual_ratio = post_residual as f64 / capacity;
    let item_ratio = item / capacity;
    let mean_ratio = (mean_residual as f64 / capacity).clamp(0.0, 1.0);

    // Reward tighter residual space, with the preference becoming stronger
    // as the stream progresses and more bins are already open.
    let urgency = (0.55 + 0.45 * progress) * (1.0 + open_bins_count as f64 / (total_items.max(1) as f64).sqrt());
    score -= 38.0 * urgency * residual_ratio * residual_ratio;

    // A nonlinear interaction between remaining space and stream progress:
    // late in the stream, fragmented leftovers are especially costly.
    score += 21.0 * progress * progress * residual_ratio * residual_ratio;

    // Mildly discourage placing an item when it leaves substantially more
    // space than the average open bin, unless doing so is the only option.
    let relative_remainder = (post_residual as f64 - mean_residual) / capacity;
    score += 13.0 * relative_remainder * relative_remainder;

    // Favor bins whose residual space is well matched to the current item.
    let fit_error = (bin_residual as f64 - item) / capacity;
    score += 10.0 * fit_error * fit_error;

    // Lookahead is used smoothly: large future items make small remainders
    // more valuable, while the current item's size remains the main signal.
    if next_item_size > 0 {
        let future_ratio = next_item_size as f64 / capacity;
        let future_fit = if (post_residual as f64) >= next_item_size as f64 {
            1.0
        } else {
            0.0
        };
        score += 7.0 * (1.0 - future_fit) * future_ratio * (1.0 - progress);
        score -= 4.0 * future_fit * future_ratio * residual_ratio;
    }

    // When only one fitting bin remains, avoid needlessly creating a new
    // bin, but retain a small incentive to open one if the fit is very poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - item_ratio);
    }

    // An empty bin is attractive mainly when existing bins are poorly filled.
    if bin_residual == bin_capacity {
        let pressure = mean_ratio.clamp(0.0, 1.0);
        score += 18.0 * pressure * pressure;
        score += 8.0 * item_ratio * (1.0 - progress);
    }

    score
}
